import '@emotion/react';

declare module '@emotion/react' {
  export interface Theme {
    colors: {
      background: string;
      text: string;
      primary: string;
      secondary: string;
      accent: string;
      gradient: string;
    }
  }
}

const theme = {
  colors: {
    background: '#0a0a0a',
    text: '#f5f6fa',
    primary: '#00a8ff',
    secondary: '#00d2d3',
    accent: '#9c88ff',
    gradient: 'linear-gradient(135deg, #0a0a0a 0%, #1a1a1a 100%)'
  }
};

export default theme;
